def group_by(entries):
    groups = {}
    for entry in entries:
        service, message = entry.split(":", 1)
        groups.setdefault(service, []).append(message)
    return groups

alt:
def group_by(entries):
    groups = {}
    for e in entries:
        s, m = e.split(":", 1)
        if s not in groups:
            groups[s] = []
        groups[s].append(m)
    return groups
